import re, glob, os

tab = {}
for line in open('draft/numerals.md'):
    m = re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|', line)
    if m:
        tab[int(m.group(1))] = m.group(2)
print("table:", sorted(tab))

used = {}
for f in sorted(glob.glob('draft/*.md')) + sorted(glob.glob('figures/*.md')):
    if f.endswith('numerals.md'):
        continue
    txt = open(f).read()
    nums = set(int(n) for n in re.findall(r'(?<![\d.])(\d{2})(?![\d])', txt))
    used[f] = nums
    bad = nums - set(tab)
    print(os.path.basename(f), sorted(nums), ("UNKNOWN:" + str(sorted(bad))) if bad else "")

allused = set().union(*used.values())
print("in table but unused:", sorted(set(tab) - allused))

